// Package tlsfix provides TLS-capture fixtures for tests. T50 made the
// captured browser spec mandatory for every tls-client construction, so
// any test that builds a client (or a full engine runtime) needs a valid
// capture on disk or in memory. The fixture hello is generated by a real
// uTLS Chrome client against a local pipe, so it is genuinely buildable
// for the transport — not a hand-rolled hex blob.
package tlsfix

import (
	"context"
	"net"
	"testing"
	"time"

	tls "github.com/bogdanfinn/utls"

	"hhauto/internal/tlsfp"
)

// Spec returns a parsed capture of a real uTLS Chrome-133 ClientHello
// stamped with the given User-Agent.
func Spec(t testing.TB, ua string) *tlsfp.Spec {
	t.Helper()
	clientSide, tapSide := net.Pipe()
	hello := make(chan []byte, 1)
	go func() {
		raw, err := tlsfp.ReadClientHelloRecord(tapSide)
		if err == nil {
			hello <- raw
		}
		_ = tapSide.Close()
	}()
	uconn := tls.UClient(clientSide, &tls.Config{ServerName: "hh.ru"}, tls.HelloChrome_133, true, false, true)
	go func() { _ = uconn.HandshakeContext(context.Background()) }()
	var raw []byte
	select {
	case raw = <-hello:
	case <-time.After(10 * time.Second):
		t.Fatal("no ClientHello from the uTLS client")
	}
	_ = clientSide.Close()
	spec, err := tlsfp.ParseClientHello(raw, tlsfp.CaptureMeta{
		CapturedAt: time.Now().UTC().Format(time.RFC3339),
		BrowserVer: "chrome-test",
		Host:       "hh.ru",
		UserAgent:  ua,
	})
	if err != nil {
		t.Fatalf("tlsfix: parse capture: %v", err)
	}
	return spec
}

// Seed persists a fixture capture at the default spec path under dataDir,
// so engine builds and CLI runs find it instead of launching a real
// capture browser.
func Seed(t testing.TB, dataDir, ua string) {
	t.Helper()
	if err := Spec(t, ua).Save(tlsfp.DefaultPath(dataDir)); err != nil {
		t.Fatalf("tlsfix: seed spec: %v", err)
	}
}
